<!DOCTYPE html>
<html><head><title>Orders</title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600&display=swap" rel="stylesheet"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:'Inter',sans-serif;background:#0a0a0a;color:#e8e0d8;}.sidebar{position:fixed;left:0;top:0;width:260px;height:100%;background:#111;padding:2rem 1rem;}.sidebar a{display:block;padding:0.8rem 1rem;color:#e8e0d8;text-decoration:none;margin:0.5rem 0;border-radius:8px;}.sidebar a:hover,.sidebar a.active{background:#d4af7a;color:#0a0a0a;}.content{margin-left:260px;padding:2rem;}table{width:100%;border-collapse:collapse;}th,td{padding:1rem;text-align:left;border-bottom:1px solid #222;}.status{background:#d4af7a;color:#0a0a0a;padding:0.2rem 0.5rem;border-radius:20px;font-size:0.7rem;}</style></head>
<body><div class="sidebar"><h2 style="color:#d4af7a;">Jenny's Admin</h2><a href="index.php"><i class="fas fa-dashboard"></i> Dashboard</a><a href="products.php"><i class="fas fa-box"></i> Products</a><a href="categories.php"><i class="fas fa-tags"></i> Categories</a><a href="orders.php" class="active"><i class="fas fa-shopping-cart"></i> Orders</a><a href="reports.php"><i class="fas fa-chart-line"></i> Reports</a><a href="logout.php" style="color:#ff4444; margin-top:2rem;"><i class="fas fa-sign-out-alt"></i> Logout</a></div>
<div class="content"><h1>Orders</h1><table><thead><tr><th>Order ID</th><th>Customer</th><th>Date</th><th>Total</th><th>Status</th></tr></thead><tbody>
<?php $orders=$pdo->query("SELECT o.*,c.name as client_name FROM orders o LEFT JOIN clients c ON o.client_id=c.id ORDER BY o.id DESC"); while($order=$orders->fetch()): ?>
<tr><td>#<?php echo $order['id']; ?></td><td><?php echo htmlspecialchars($order['client_name']); ?></td><td><?php echo date('d M Y',strtotime($order['order_date'])); ?></td><td>$<?php echo number_format($order['total_amount'],2); ?></td><td><span class="status"><?php echo $order['status']; ?></span></td></tr>
<?php endwhile; ?>
</tbody></table></div></body></html>